# POST /api/sheets/{sheetId}/claims/{claimId}/reject?reason=... — a steward rejects a PENDING claim with
# a reason: it goes back to OPEN; refused (409) for anyone else or when it is not PENDING, (400) with no reason.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
